def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from collections import deque
    from fractions import Fraction

    jump = dict(jumps)
    destination = list(range(n + 1))

    for cell in jump:
        path = []
        current = cell
        while current in jump and destination[current] == current:
            path.append(current)
            current = jump[current]
        for visited in path:
            destination[visited] = destination[current]

    transitions = [[] for _ in range(n)]
    reverse = [[] for _ in range(n + 1)]

    for cell in range(n):
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            landing = destination[landing]
            transitions[cell].append(landing)
            reverse[landing].append(cell)

    reachable = [False] * (n + 1)
    reachable[0] = True
    queue = deque([0])
    while queue:
        cell = queue.popleft()
        if cell == n:
            continue
        for landing in transitions[cell]:
            if not reachable[landing]:
                reachable[landing] = True
                queue.append(landing)

    can_finish = [False] * (n + 1)
    can_finish[n] = True
    queue = deque([n])
    while queue:
        cell = queue.popleft()
        for previous in reverse[cell]:
            if not can_finish[previous]:
                can_finish[previous] = True
                queue.append(previous)

    if any(reachable[cell] and not can_finish[cell] for cell in range(n)):
        return None

    states = [cell for cell in range(n) if reachable[cell]]
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    matrix = [[0] * (size + 1) for _ in range(size)]
    for cell in states:
        row = matrix[index[cell]]
        row[index[cell]] = m
        row[size] = m
        for landing in transitions[cell]:
            if landing != n:
                row[index[landing]] -= 1

    # Fraction-free Gaussian elimination.
    previous_pivot = 1
    for col in range(size - 1):
        if matrix[col][col] == 0:
            for row in range(col + 1, size):
                if matrix[row][col] != 0:
                    matrix[col], matrix[row] = matrix[row], matrix[col]
                    break

        pivot = matrix[col][col]
        for row in range(col + 1, size):
            factor = matrix[row][col]
            for j in range(col + 1, size + 1):
                matrix[row][j] = (
                    matrix[row][j] * pivot - factor * matrix[col][j]
                ) // previous_pivot
            matrix[row][col] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for row in range(size - 1, -1, -1):
        value = Fraction(matrix[row][size])
        for col in range(row + 1, size):
            value -= matrix[row][col] * solution[col]
        solution[row] = value / matrix[row][row]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
